import{_ as o}from"./chunks/65f4bf7ef3b9f06de912.B7NgZb8P.js";import{_ as r,C as p,o as s,c as i,j as a,a as n,E as l,a5 as m}from"./chunks/framework.DNkHA0lr.js";const _=JSON.parse('{"title":"如何通过模仿走向成功（而不是平庸）","description":"","frontmatter":{"title":"如何通过模仿走向成功（而不是平庸）","originalTitle":"How To Copy Your Way To Success (Instead Of Mediocrity)","date":"2022-05-14","originalUrl":"https://thedankoe.com/letters/how-to-copy-your-way-to-success-instead-of-mediocrity/","minutes":10,"sourceHash":"5f5b1e13525e5c0c4fd1b8b5f765c77a00eefcffe21ac2c0d4b6408613687ff2","translation":"AI-assisted, block-aligned; not official","head":[["link",{"rel":"canonical","href":"https://thedankoe.com/letters/how-to-copy-your-way-to-success-instead-of-mediocrity/"}]]},"headers":[],"relativePath":"letters/how-to-copy-your-way-to-success-instead-of-mediocrity.md","filePath":"letters/how-to-copy-your-way-to-success-instead-of-mediocrity.md"}'),c={name:"letters/how-to-copy-your-way-to-success-instead-of-mediocrity.md"};function h(d,e,f,u,b,y){const t=p("ArticleMeta");return s(),i("div",null,[e[0]||(e[0]=a("h1",{id:"如何通过模仿走向成功-而不是平庸",tabindex:"-1"},[n("如何通过模仿走向成功（而不是平庸） "),a("a",{class:"header-anchor",href:"#如何通过模仿走向成功-而不是平庸","aria-label":'Permalink to "如何通过模仿走向成功（而不是平庸）"'},"​")],-1)),l(t),e[1]||(e[1]=m('<p><a href="https://www.youtube.com/embed/ShdG7cgGA2M?feature=oembed" target="_blank" rel="noreferrer">观看原文视频</a></p><p><a href="https://open.spotify.com/embed/episode/7p8tPvPrwT6dhQfszvYJh8?si=85aaf8da89014e0a&amp;utm_source=oembed" target="_blank" rel="noreferrer">观看原文视频</a></p><p>当我读一本新书时，我通常根据<strong>一件事</strong>来判断自己是否想继续读下去：</p><p>我能<em>感觉</em>到大脑的某些区域被点亮了。纸上的文字直击我的灵魂，给了我一直苦苦寻找的答案。我的好奇心将我拉得越来越深。各种疯狂的想法涌入脑海，让我过了就寝时间（我现在大概晚上9点就睡）都无法入眠。我<em>必须</em>继续读下去。我<em>必须</em>继续深入探究。我<em>必须</em>了解关于这个主题的任何事和所有事。我必须获取所有的视角，以便在未来的对话中能够巧妙地游刃有余。</p><p>如果一本书不能给我这种感觉，我就会把它放回书架，留着以后再说。我为什么要浪费时间读自己不感兴趣的东西呢？我们大脑中的这种奖励机制存在是有原因的，对吧？为了帮助我们朝着积极的人生方向前进？为了给我们反馈，让我们在噪音中分辨出信号？很多人用这个机制让自己沉溺于多巴胺之中——电子游戏、梗图（memes）、自慰，以及任何其他用来替代追求好奇心的人造替代品。</p><p>真正的问题在于；这有用吗？追求我的兴趣能带来现实世界的价值吗？我对好奇心的探索会有明确的目的吗？除了让我的大脑感觉良好并拓宽我的知识深度之外？</p><p>我们来探索一下。</p><h2 id="你天生就是个模仿者" tabindex="-1">你天生就是个模仿者 <a class="header-anchor" href="#你天生就是个模仿者" aria-label="Permalink to &quot;你天生就是个模仿者&quot;">​</a></h2><p>从时间的源头开始（只要时间对你而言一开始，也就是出生），你就一直在模仿——或者说复制——你周围的人。不然你怎么生存？</p><p>小时候，你模仿你的父母。你学会了说话、走路、吃饭，并（希望你）学会了正确上厕所。随着你长大，文化开始发挥作用。学校系统给了每个人相同的课程。你的朋友把他们的观点投射到你身上（而那是他们从父母那里模仿来的）。当你在学校系统中不断升学时，那种神奇的化学物质——多巴胺——发挥了从噪音中分离出信号的作用。你会去模仿那些点亮你部分大脑的事物。</p><p>这不是问题。当<em>执念（attachment）</em>加入进来时，问题才会暴露出来。我们无意识地吸收的这些特质、偏见、信念、价值观和视角，塑造了我们的身份。</p><p>大脑讨厌无序。它需要一个目标层级来获得清晰度并蓬勃发展。无论你是否意识到，你的大脑都会构建一个目标层级。文化和职场生活方式都有大大小小的目标，引导着人们的行动。上学（目标1），找工作（目标2），退休（目标3）——但这要付出什么代价？</p><p>大脑需要一个故事来抓住并理解这一切。大脑通过了解前因后果来理解这个世界。我们必须知道在心理的过去发生了什么，才能对未来有一种确定<em>感</em>。没有了确定性，焦虑、压力和熵的产物就会占据主导。</p><blockquote><p>要克服当代生活的焦虑和抑郁，个体必须在一定程度上独立于社会环境，使其不再完全受制于环境的奖惩。要实现这种自决，一个人必须学会自我奖励。她必须培养出无论外部环境如何，都能发现乐趣和目标的能力。——米哈里·契克森米哈赖 (Mihaly Csikszentmihalyi)</p></blockquote><p>如果有人没有<em>意识</em>到这个模仿过程，他们就会依附于自己的身份——这层帮助大脑理解自身存在的故事。当他们的身份遇到威胁时，他们的生存雷达就会响起。他们的世界观受到了威胁。大脑将这种身份威胁等同于潜在的死亡。人类是唯一会这样做的存在。如果没有人把它叫做手机，它还是手机吗？如果没有人叫我 Dan，我还是 Dan 吗？如果没有一种信念来合理化这一切——我甚至还存在吗？</p><p>这也是我建议写下并打磨你的愿景的另一个原因。拥有一个由<em>你</em>创造并与<em>你</em>想过的生活相一致的目标层级非常重要。清晰的愿景能为你日常的行动带来清晰度。它给你的大脑带来秩序。它能消除你生活中的所有压力和焦虑——<em>前提是</em>，这个目标层级具有内在动机（参见：<a href="https://youtu.be/3kSMxMlbktc" target="_blank" rel="noreferrer">好奇心、热情、目标</a>、价值观等）。你一开始可能做不对。这是一个实验、测试和迭代的终生过程。把它写下来。即使你<em>觉得</em>第一次可能行不通。</p><p>这就是你让无意识变得有意识的方法。</p><blockquote><p>一个能够掌控意识的人，其标志是能够随意集中注意力，对分心事物视而不见，能够持续集中精力直到达成目标，并且不会过度沉迷。而能做到这一点的人，通常也很享受日常生活的平凡过程。——米哈里·契克森米哈赖</p></blockquote><p><em><strong>成功是一场关于聪明模仿的游戏。</strong></em> 模仿可能会对我们的未来有害——但模仿本身是无法逃避的。我们正在模仿周围的一切。我们处理接触到的信息，然后它被储存在我们大脑的某个地方。</p><p>为了充分利用这种生存机制，我们需要有意识地去分辨自己在模仿什么，以及模仿谁。如果我们让自己接触某个人，他们传达的信息是什么？他们是在宣扬负面情绪和让你轻易接受的限制性信念吗？还是在倡导成长、教育，并向你展示如何朝着积极的人生方向前进？他们的目标层级是什么，和我们的目标层级一致吗？</p><p>再次强调，这就是好奇心发挥作用的地方。追求你的好奇心就是你聪明模仿的方式。怎么做？通向好奇心的第一步是“倾听”——或者说感受——你脑海中的多巴胺水平。当你分心时，这几乎是不可能的。或者当你沉溺于廉价刺激带来的多巴胺中时。或者沿着别人为你设定的道路前行时。等等。</p><h2 id="你是一个视角的容器" tabindex="-1">你是一个视角的容器 <a class="header-anchor" href="#你是一个视角的容器" aria-label="Permalink to &quot;你是一个视角的容器&quot;">​</a></h2><p><img src="'+o+'" alt=""></p><p>聪明的模仿</p><p>一切皆为视角。现实即视角。<em>把视角（perspective）想象成相机，把认知（perception）想象成镜头。</em> 两者结合创造了你的世界观。说到底，每个人都在试图基于自己的世界观来捍卫自己的视角。你可以在评论区、新闻中、与伴侣的争吵中看到它，无处不在。这是一种必要的练习；能够把你的相机拉远，看到大局，并带着你的相机环游世界。<em>这就是你不再对无关紧要的事情产生应激反应的方法。</em> 你改变视角，是为了让自己建立起更有利的认知。找到一个有利认知（对情况的解释）的制高点，就是你在生活中做出积极决策的方法。</p><h3 id="关于做出更好选择的附加课" tabindex="-1"><strong>关于做出更好选择的附加课：</strong> <a class="header-anchor" href="#关于做出更好选择的附加课" aria-label="Permalink to &quot;**关于做出更好选择的附加课：**&quot;">​</a></h3><p>Terrence 在刷社交媒体。他看到一条让他生气的帖子。这种反应是由多年的模仿、条件反射，以及他人视角投射出来的信念和观点所造成的程序设定引起的。</p><p>Terrance 留了一条刻薄的评论，感受到了多巴胺的喷涌，并享受着这种最终会反噬他的即时满足感。这条评论留在那里，激怒了更多人，并引发了连锁反应，让一群多巴胺瘾君子在他们的脑海中固化着自己差劲的视角。</p><p>现在，<em>想象一下简单的停顿和重构带来的力量</em>。如果 Terrence 转换到了一个能为好奇心腾出空间的视角，他本可以从起初惹怒他的事情中提取出积极的教训。他不预设全盘事实，而是接受对方有不同的视角。这种视角由他们自己的愿景、目标、经历、价值观以及其他一切根本无法预设的东西组成。</p><p>只需一个简单的停顿，Terrence 本可以敞开心扉，迎接一个能将他推向全新人生方向的机会。</p><h3 id="回到人类是视角的容器这个话题-以及它与提升你自身价值的关系" tabindex="-1"><strong>回到人类是视角的容器这个话题（以及它与提升你自身价值的关系）：</strong> <a class="header-anchor" href="#回到人类是视角的容器这个话题-以及它与提升你自身价值的关系" aria-label="Permalink to &quot;**回到人类是视角的容器这个话题（以及它与提升你自身价值的关系）：**&quot;">​</a></h3><p>注意力是新的货币。新奇的事物能抓住注意力。新颖的视角会让人们愿意听你说话，而不是别人。我们在《The Koe Letter》中讨论了很多关于创业的话题，但这远不止于此。新颖、积极的视角是让人记住你的关键。帮助人们理清思路——在他们脑海中将那些点连接起来——会将你的话刻在他们的脑子里。</p><p>新颖的视角能让人们雇佣你，而不是下一个人。它们是真实性的基础——对当下情况给出你独特、内在且未经粉饰的视角。新颖且经过深思熟虑的视角，是你看清事物本质的关键——这样你就能将其转化为你的优势。</p><p><em><strong>如果你掌握了视角的艺术，你就掌握了思维的游戏。</strong></em></p><h2 id="聪明模仿的流程" tabindex="-1">聪明模仿的流程 <a class="header-anchor" href="#聪明模仿的流程" aria-label="Permalink to &quot;聪明模仿的流程&quot;">​</a></h2><p>这不仅仅适用于创业。追求你的好奇心、在网上发帖，以及建立数字杠杆，是每个人都可以做到的事。雇主们正在积极招募拥有精美数字简历的人。个人品牌是一个项目，你可以把学到的所有东西都应用和测试在上面（这能让你学得更快）。正如我们上周所讨论的，世界正在重新向信任、简单和个性化转变。</p><p>你通过保持真实来建立<em>信任</em>。你通过以一种合乎逻辑的方式提炼信息来表达<em>简单</em>。你通过对你生活的结果负起全责来践行<em>个性</em>。</p><p>你通过追求好奇心、提炼学到的知识，并通过你独特的视角在网上发帖来完成以上所有事情。（这正是我现在在做的事）。</p><p>如果你想开始建立忠实的受众群体、数字杠杆，并让机会主动找上门，这里有我用于浓缩和理解知识的“聪明模仿流程”。</p><h3 id="第一步-选择3-5位你渴望成为的那种-导师-。" tabindex="-1"><strong>第一步）选择3-5位你渴望成为的那种“导师”。</strong> <a class="header-anchor" href="#第一步-选择3-5位你渴望成为的那种-导师-。" aria-label="Permalink to &quot;**第一步）选择3-5位你渴望成为的那种“导师”。**&quot;">​</a></h3><p><em>你吸收什么就会成为什么，所以根据你渴望成为的人去吸收内容。</em></p><p>要让这个过程变得简单，写下3-5个改变了<em>你</em>视角的那些人的名字。</p><p>你最喜欢、逢人便推荐的书是什么？写下作者的名字。</p><p>那个让你停不下来去看的 YouTuber、播客主播或博主是谁？那个每次发内容都能“震撼你大脑”的人是谁？</p><p>你关注的哪些社交媒体账号会让你想：“他们是怎么说得这么精辟的？”</p><p>因为这就是关键所在……并不是每个人都这么想。只有你会。这些“导师”的组合与<em>链接</em>，就是你如何开创自己的细分领域、视角，以及如何创作出让你脱颖而出的内容的方式。</p><p>重新读一遍你最喜欢的书的第一章——我保证你的大脑会被点亮。</p><h3 id="第二步-不要消费。去研究。" tabindex="-1"><strong>第二步）不要消费。去研究。</strong> <a class="header-anchor" href="#第二步-不要消费。去研究。" aria-label="Permalink to &quot;**第二步）不要消费。去研究。**&quot;">​</a></h3><p>消费内容意味着你没拿它做任何事。你没有在<em>使用</em>它（参见：普遍的“使用法则” Law of Use）。</p><p>当你采用研究者的<em>视角</em>时，你会把一切都看作是实验。你研究的一切都会获得实用价值。你测试各种想法，通过连接这些想法形成理论，确定这在现实世界中如何产生结果，然后将它们转化为能为他人带来结果的可复制流程（这就是人们在个人品牌下销售的东西，这也是我想出这个流程的方法 😉)</p><p><a href="https://open.spotify.com/episode/5DdgoAufTrFF6tzd4B6zXy?si=f1e8f435c0004c1a" target="_blank" rel="noreferrer">我有一期名为“如果你想赚更多钱，就停止学习”（Stop learning if you want to make more money）的播客，对此进行了更深入的探讨。</a></p><h3 id="步骤-3-触及你的内心并把它写下来。" tabindex="-1"><strong>步骤 3) 触及你的内心并把它写下来。</strong> <a class="header-anchor" href="#步骤-3-触及你的内心并把它写下来。" aria-label="Permalink to &quot;**步骤 3) 触及你的内心并把它写下来。**&quot;">​</a></h3><p>如果想让这奏效，你就不能沉溺于现代的各种分心事物中。你必须为多巴胺留出空间，让它能准确地区分信号与噪音。</p><p>当你顺着自己的好奇心进行研究时，先不要记笔记。等待那个吸引你注意力的全新视角。<em>感受</em>那种兴奋。<em>感受</em>你的注意力逐渐收拢，并更加仔细地倾听（或阅读）。</p><p>这就是你要写在笔记里的东西。</p><h3 id="步骤-4-剖析与提炼。" tabindex="-1"><strong>步骤 4) 剖析与提炼。</strong> <a class="header-anchor" href="#步骤-4-剖析与提炼。" aria-label="Permalink to &quot;**步骤 4) 剖析与提炼。**&quot;">​</a></h3><p>这是培养独特视角的关键。在实验中，你剖析某个事物是为了了解它的各个组成部分。如果你不这样做，你对这个话题的理解就会很肤浅（社交媒体上的大多数人都是如此）。肤浅的理解会阻碍你建立更深层次的连接，而正是这种连接能让你从人群中脱颖而出。</p><p><a href="https://7daystogeniusideas.com/" target="_blank" rel="noreferrer">我免费的7天创意挑战（7 day creative challenge）为你提供了这个流程的模板（以及关于我如何使用它的深入指南）。</a></p><p><em>基于你在笔记中写下的内容，你要做以下事情：</em></p><ul><li>它相关的主题</li><li>简要总结<em>你</em>是如何理解它的。</li><li>与该主题相关的常见问题。</li><li>克服这些问题的常见好处。</li><li>人们对解决这些问题所持有的反对意见或限制性信念。</li><li>你在该主题上的个人经历和故事</li><li>克服该问题的循序渐进的流程</li></ul><p>现在，把这些都写下来之后，你要把它们<em>全部</em>总结成一个用一句话表达的核心理念（big idea）。这会向你证明，你可以从自己独特的视角中创造出深刻的、引人入胜的名言警句。</p><p>“好吧，Dan，但我拿这些信息能干什么呢？”</p><p>从本质上讲，你刚刚以一个新颖且具有说服力的视角，为一篇文章、一个视频、一个长推文（thread）、多条推文、一个产品以及一个落地页创建了提纲。是的。我确实把所有这些都提炼成了一个流程。</p><p>如果你对营销、销售或内容心理学有基础的了解——我知道你能看懂这其中的威力。</p><p>当你这样做几个月后，你就会建立起一张具有现实世界实用价值的天才想法网络。这些想法能吸引他人。这些想法可以变现。这些想法为新想法腾出了空间——加速人类的进化。是的，想法正是推动人类进化向前的核心事物。它们层层叠加。记住……故事。一件事必须发生在另一件事之前——一个绝妙的想法绝对能改变人类的方向……或者仅仅是改变你生活的方向。</p><p>如果你喜欢这期 The Koe Letter，考虑把它分享给朋友吧。</p><p>如果这封信是别人分享给你的，<a href="https://links.thedankoe.com/#letter" target="_blank" rel="noreferrer">你可以在这里订阅，每周六早上直接在你的收件箱里收到它们。</a></p><hr><p><a href="/en/letters/how-to-copy-your-way-to-success-instead-of-mediocrity">查看英文存档</a> · <a href="/letters/">返回全部文章</a></p>',69))])}const q=r(c,[["render",h]]);export{_ as __pageData,q as default};
